import { DirectoryInfo } from '@/utils/exampleFileUtils';
        export const FILE_INFO: DirectoryInfo = {"isFile":false,"name":"react-chat","path":"/","children":[{"isFile":false,"name":"src","path":"/src","children":[{"isFile":true,"isOpen":false,"language":"css","name":"App.css","path":"/src/App.css","content":"/* yorkie.dev's Shared Canvas: warm neutrals, orange for the brand, and the\n * other hues for people only. */\n:root {\n  color-scheme: light;\n  --gray-900: #332e2b;\n  --gray-800: #514c49;\n  --gray-700: #6e6966;\n  --gray-600: #807b78;\n  --gray-500: #a6a19e;\n  --gray-400: #c2bdba;\n  --gray-300: #e2dedb;\n  --gray-200: #efeceb;\n  --gray-100: #f5f3f1;\n  --gray-50: #faf8f6;\n  --gray-000: #fefdfb;\n  --orange-0: #fc8539;\n  --orange-dark: #f27b2f;\n  --orange-alpha: rgb(252 133 57 / 32%);\n  --success: #10b266;\n  --danger: #e93d47;\n  --blue: #3c9af1;\n  --green: #23c176;\n  --purple: #855cf9;\n  --yellow: #fdc433;\n  --red: #f44954;\n  --font:\n    Pretendard, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto,\n    'Helvetica Neue', Arial, sans-serif;\n  --radius-sm: 4px;\n  --radius-md: 8px;\n  --rail-width: 176px;\n}\n\n* {\n  box-sizing: border-box;\n}\n\nhtml,\nbody,\n#root {\n  height: 100%;\n}\n\nbody {\n  margin: 0;\n  background: var(--gray-000);\n  color: var(--gray-900);\n  font: 14px/22px var(--font);\n  -webkit-font-smoothing: antialiased;\n}\n\n::selection {\n  background: var(--orange-alpha);\n}\n\n:focus-visible {\n  outline: 2px solid var(--orange-0);\n  outline-offset: 2px;\n}\n\nbutton,\ntextarea {\n  font: inherit;\n  color: inherit;\n}\n\nbutton {\n  cursor: pointer;\n}\n\nbutton:disabled {\n  cursor: not-allowed;\n}\n\nh2 {\n  margin: 0;\n}\n\n/* People's colors. `data-color` is set on dots, avatars and own reactions. */\n[data-color='blue'] {\n  --peer: var(--blue);\n  --peer-ink: #fff;\n}\n[data-color='green'] {\n  --peer: var(--green);\n  --peer-ink: #fff;\n}\n[data-color='purple'] {\n  --peer: var(--purple);\n  --peer-ink: #fff;\n}\n[data-color='yellow'] {\n  --peer: var(--yellow);\n  --peer-ink: var(--gray-900);\n}\n[data-color='red'] {\n  --peer: var(--red);\n  --peer-ink: #fff;\n}\n[data-color='orange'] {\n  --peer: var(--orange-0);\n  --peer-ink: #fff;\n}\n\n/* Layout */\n.chat {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  container: chat / inline-size;\n}\n\n.chat__body {\n  position: relative;\n  display: flex;\n  flex: 1;\n  min-height: 0;\n}\n\n.state-message {\n  margin: 48px 16px;\n  color: var(--gray-700);\n  text-align: center;\n}\n\n/* Example header (shared by the examples) */\n.example-header {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 4px 16px;\n  min-height: 56px;\n  padding: 8px 16px;\n  background: var(--gray-000);\n  border-bottom: 1px solid var(--gray-300);\n}\n\n.example-header__intro {\n  min-width: 0;\n}\n\n.example-header__title {\n  margin: 0;\n  font-size: 16px;\n  line-height: 24px;\n  font-weight: 600;\n}\n\n.example-header__hint {\n  margin: 0;\n  color: var(--gray-700);\n}\n\n.example-header a {\n  color: var(--gray-900);\n  text-decoration: underline;\n  text-decoration-color: var(--orange-0);\n  text-underline-offset: 3px;\n  border-radius: 2px;\n}\n\n.example-header a:hover {\n  text-decoration-thickness: 2px;\n}\n\n.example-header__meta {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.status {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  color: var(--gray-700);\n  white-space: nowrap;\n}\n\n.status__dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background: var(--gray-500);\n}\n\n.status[data-status='connected'] .status__dot {\n  background: var(--success);\n}\n\n.status[data-status='error'] .status__dot {\n  background: var(--danger);\n}\n\n/* Rail */\n.rail {\n  flex: none;\n  width: var(--rail-width);\n  overflow-y: auto;\n  padding: 8px 0 16px;\n  background: var(--gray-50);\n  border-right: 1px solid var(--gray-400);\n}\n\n.rail__heading {\n  padding: 16px 16px 4px;\n  font-size: 12px;\n  line-height: 16px;\n  font-weight: 500;\n  color: var(--gray-700);\n}\n\n.rail__heading:first-child {\n  padding-top: 8px;\n}\n\n.rail__list {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.rail__channel {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  width: 100%;\n  padding: 4px 16px;\n  border: 0;\n  background: none;\n  color: var(--gray-700);\n  text-align: left;\n  transition: background-color 0.2s;\n}\n\n.rail__channel:hover:not(:disabled) {\n  background: var(--gray-100);\n}\n\n.rail__channel[aria-current='page'] {\n  background: var(--gray-200);\n  color: var(--gray-900);\n  font-weight: 600;\n}\n\n.rail__channel[aria-current='page'] .rail__hash {\n  color: var(--orange-dark);\n}\n\n.rail__channel:disabled {\n  color: var(--gray-500);\n}\n\n.rail__channel:focus-visible {\n  outline-offset: -2px;\n}\n\n.rail__name {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.rail__hash {\n  margin-right: 2px;\n  color: var(--gray-500);\n}\n\n.dots {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: flex-end;\n  gap: 3px;\n  max-width: 56px;\n}\n\n.dot {\n  flex: none;\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background: var(--peer, var(--gray-400));\n}\n\n.rail__person {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 2px 16px;\n  color: var(--gray-800);\n}\n\n.rail__person-name {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.rail__you {\n  color: var(--gray-600);\n}\n\n.rail__alone {\n  margin: 4px 16px 0;\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--gray-700);\n}\n\n/* Channel */\n.channel {\n  position: relative;\n  display: flex;\n  flex: 1;\n  flex-direction: column;\n  min-width: 0;\n}\n\n.channel__head {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  min-height: 48px;\n  padding: 0 16px;\n  border-bottom: 1px solid var(--gray-300);\n}\n\n.channel__title {\n  font-size: 16px;\n  line-height: 24px;\n  font-weight: 600;\n}\n\n.channel__here {\n  margin: 0 0 0 auto;\n  font-size: 12px;\n  line-height: 16px;\n  color: var(--gray-700);\n  white-space: nowrap;\n}\n\n/* Shown instead of the rail in narrow panes. */\n.channel__switch {\n  display: none;\n  align-items: center;\n  gap: 4px;\n  margin-left: -8px;\n  padding: 4px 8px;\n  border: 1px solid transparent;\n  border-radius: var(--radius-sm);\n  background: none;\n  font-size: 16px;\n  line-height: 24px;\n  font-weight: 600;\n}\n\n.channel__switch:hover {\n  background: var(--gray-100);\n}\n\n/* Messages */\n.messages {\n  flex: 1;\n  min-height: 0;\n  margin: 0;\n  padding: 8px 0;\n  overflow-y: auto;\n  list-style: none;\n  overscroll-behavior: contain;\n  scrollbar-width: thin;\n  scrollbar-color: var(--gray-400) transparent;\n}\n\n.message {\n  position: relative;\n  display: flex;\n  gap: 10px;\n  padding: 6px 16px;\n}\n\n.message[data-compact] {\n  padding-top: 0;\n}\n\n.message:hover,\n.message:focus-within {\n  background: var(--gray-50);\n}\n\n.avatar,\n.avatar-gap {\n  flex: none;\n  width: 28px;\n  height: 28px;\n}\n\n.avatar {\n  display: grid;\n  place-items: center;\n  margin-top: 2px;\n  border-radius: 50%;\n  background: var(--peer);\n  color: var(--peer-ink);\n  font-size: 12px;\n  line-height: 1;\n  font-weight: 600;\n}\n\n.message__main {\n  flex: 1;\n  min-width: 0;\n}\n\n.message__meta {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  margin: 0;\n}\n\n.message__name {\n  font-weight: 600;\n}\n\n.message__time {\n  font-size: 12px;\n  line-height: 16px;\n  color: var(--gray-700);\n  font-variant-numeric: tabular-nums;\n}\n\n.message__text {\n  margin: 0;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.message__pending {\n  margin: 2px 0 0;\n  font-size: 12px;\n  line-height: 16px;\n  color: var(--gray-700);\n}\n\n.message__pending::before {\n  content: '';\n  display: inline-block;\n  width: 6px;\n  height: 6px;\n  margin-right: 6px;\n  border: 1px solid var(--gray-600);\n  border-radius: 50%;\n  vertical-align: 1px;\n}\n\n.message__extras {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 4px;\n  margin-top: 4px;\n}\n\n.reaction {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  height: 24px;\n  padding: 0 8px;\n  border: 1px solid var(--gray-300);\n  border-radius: 12px;\n  background: var(--gray-000);\n  font-size: 12px;\n  line-height: 16px;\n  transition: background-color 0.2s;\n}\n\n.reaction:hover {\n  background: var(--gray-100);\n}\n\n/* Your own reaction carries your color. */\n.reaction[aria-pressed='true'] {\n  border-color: var(--peer);\n  background: color-mix(in srgb, var(--peer) 16%, var(--gray-000));\n}\n\n.reaction__count {\n  font-weight: 600;\n  font-variant-numeric: tabular-nums;\n}\n\n.message__replies {\n  padding: 2px 4px;\n  border: 0;\n  border-radius: var(--radius-sm);\n  background: none;\n  font-size: 12px;\n  line-height: 16px;\n  font-weight: 600;\n  color: var(--gray-900);\n  text-decoration: underline;\n  text-decoration-color: var(--orange-0);\n  text-underline-offset: 3px;\n}\n\n.message__actions {\n  position: absolute;\n  top: -12px;\n  right: 16px;\n  display: flex;\n  /* Hidden but still in the tab order, so a keyboard can reach a message's\n   * first reaction or reply: focusing it reveals the bar. */\n  opacity: 0;\n  pointer-events: none;\n  gap: 2px;\n  padding: 2px;\n  border: 1px solid var(--gray-400);\n  border-radius: var(--radius-sm);\n  background: var(--gray-000);\n  box-shadow: 0 8px 8px -8px rgb(0 0 0 / 20%);\n}\n\n.message:hover .message__actions,\n.message:focus-within .message__actions {\n  opacity: 1;\n  pointer-events: auto;\n}\n\n/* Touch screens have no hover: keep the actions visible. */\n@media (hover: none) {\n  .message__actions {\n    position: static;\n    display: flex;\n    opacity: 1;\n    pointer-events: auto;\n    align-self: flex-start;\n    border: 0;\n    box-shadow: none;\n    background: none;\n  }\n}\n\n.icon-button,\n.text-button {\n  display: inline-grid;\n  place-items: center;\n  height: 28px;\n  border: 0;\n  border-radius: var(--radius-sm);\n  background: none;\n  color: var(--gray-700);\n  transition: background-color 0.2s;\n}\n\n.icon-button {\n  width: 28px;\n}\n\n.text-button {\n  padding: 0 8px;\n  font-size: 12px;\n  font-weight: 500;\n}\n\n.icon-button:hover,\n.text-button:hover {\n  background: var(--gray-100);\n  color: var(--gray-900);\n}\n\n.picker {\n  display: inline-flex;\n  gap: 2px;\n  margin-top: 6px;\n  padding: 2px;\n  border: 1px solid var(--gray-400);\n  border-radius: var(--radius-sm);\n  background: var(--gray-000);\n}\n\n.picker__emoji {\n  width: 32px;\n  height: 28px;\n  border: 0;\n  border-radius: var(--radius-sm);\n  background: none;\n  font-size: 16px;\n}\n\n.picker__emoji:hover {\n  background: var(--gray-100);\n}\n\n/* Typing line and composer */\n.typing {\n  flex: none;\n  min-height: 18px;\n  margin: 0;\n  padding: 0 16px;\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--gray-700);\n}\n\n.composer {\n  position: relative;\n  display: flex;\n  align-items: flex-end;\n  gap: 8px;\n  margin: 0 16px 12px;\n  padding: 4px 4px 4px 12px;\n  border: 1px solid var(--gray-400);\n  border-radius: var(--radius-sm);\n  background: var(--gray-000);\n}\n\n.composer:focus-within {\n  border-color: var(--gray-700);\n}\n\n.composer__input {\n  flex: 1;\n  min-width: 0;\n  padding: 3px 0;\n  border: 0;\n  outline: none;\n  resize: none;\n  background: none;\n  caret-color: var(--orange-0);\n}\n\n.composer__input::placeholder {\n  color: var(--gray-600);\n}\n\n.composer__count {\n  align-self: center;\n  font-size: 12px;\n  color: var(--gray-700);\n  font-variant-numeric: tabular-nums;\n}\n\n.composer__count[data-over] {\n  color: var(--danger);\n  font-weight: 600;\n}\n\n.composer__send {\n  display: grid;\n  flex: none;\n  place-items: center;\n  width: 28px;\n  height: 28px;\n  border: 0;\n  border-radius: var(--radius-sm);\n  background: var(--orange-0);\n  color: #fff;\n  transition: background-color 0.2s;\n}\n\n.composer__send:hover:not(:disabled) {\n  background: var(--orange-dark);\n}\n\n.composer__send:disabled {\n  background: var(--gray-200);\n  color: var(--gray-500);\n}\n\n/* Thread sheet */\n.thread {\n  position: absolute;\n  inset: 0 0 0 auto;\n  z-index: 2;\n  display: flex;\n  flex-direction: column;\n  width: min(320px, 100%);\n  background: var(--gray-000);\n  border-left: 1px solid var(--gray-400);\n  box-shadow: 0 20px 24px -12px rgb(0 0 0 / 20%);\n}\n\n.thread__head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  min-height: 48px;\n  padding: 0 8px 0 16px;\n  border-bottom: 1px solid var(--gray-300);\n}\n\n.thread__title {\n  font-size: 14px;\n  line-height: 22px;\n  font-weight: 600;\n}\n\n.thread__parent {\n  padding-bottom: 12px;\n}\n\n.thread__count {\n  margin: 0 16px 4px;\n  padding-top: 8px;\n  border-top: 1px solid var(--gray-300);\n  font-size: 12px;\n  line-height: 16px;\n  color: var(--gray-700);\n}\n\n.thread .composer {\n  margin-top: 8px;\n}\n\n/* The homepage says how to try it; in a pane the hint only costs a row. */\n@container chat (max-width: 719px) {\n  .example-header__hint {\n    display: none;\n  }\n}\n\n/* Narrow panes: the rail becomes a list over the channel. */\n@container chat (max-width: 479px) {\n  /* Hidden with visibility, not display: showing it again must not replay\n   * every dot's arrival. Hidden, it is also out of the tab order. */\n  .rail {\n    position: absolute;\n    inset: 0 auto 0 0;\n    z-index: 3;\n    visibility: hidden;\n    width: min(240px, 85%);\n    box-shadow: 0 20px 24px -12px rgb(0 0 0 / 20%);\n  }\n\n  .chat__body[data-rail-open] .rail {\n    visibility: visible;\n  }\n\n  .channel__title {\n    display: none;\n  }\n\n  .channel__switch {\n    display: inline-flex;\n  }\n\n  .thread {\n    width: 100%;\n    border-left: 0;\n  }\n}\n\n/* The yorkie.dev preview can be short: keep only the essentials. */\n@media (max-height: 420px) {\n  .example-header {\n    min-height: 0;\n    padding-block: 4px;\n  }\n\n  .example-header__hint {\n    display: none;\n  }\n\n  .channel__head,\n  .thread__head {\n    min-height: 40px;\n  }\n\n  .rail__heading {\n    padding-top: 8px;\n  }\n}\n\n/* Online/offline switch */\n.switch {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 4px 8px;\n  border: 1px solid var(--gray-400);\n  border-radius: var(--radius-sm);\n  background: var(--gray-000);\n  font-size: 12px;\n  line-height: 16px;\n  font-weight: 500;\n  white-space: nowrap;\n  transition: background-color 0.2s;\n}\n\n.switch:hover:not(:disabled) {\n  background: var(--gray-100);\n}\n\n.switch__track {\n  position: relative;\n  width: 24px;\n  height: 14px;\n  border-radius: 7px;\n  background: var(--gray-400);\n  transition: background-color 0.2s;\n}\n\n.switch[data-online] .switch__track {\n  background: var(--success);\n}\n\n.switch__thumb {\n  position: absolute;\n  top: 2px;\n  left: 2px;\n  width: 10px;\n  height: 10px;\n  border-radius: 50%;\n  background: var(--gray-000);\n  transition: transform 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n.switch[data-online] .switch__thumb {\n  transform: translateX(10px);\n}\n\n/* While offline the page itself says so: the composer keeps working, the\n * rest of the room is out of reach. */\n.status[data-status='offline'] .status__dot {\n  background: var(--gray-500);\n}\n\n.scrim {\n  display: none;\n}\n\n@container chat (max-width: 479px) {\n  .scrim {\n    position: absolute;\n    inset: 0;\n    z-index: 2;\n    display: block;\n    border: 0;\n    background: rgb(51 46 43 / 24%);\n    cursor: default;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .switch__thumb {\n    transition: none;\n  }\n}\n\n/* Wide panes have room for the thread beside the messages. */\n@container chat (min-width: 900px) {\n  .channel:has(.thread) {\n    padding-right: 320px;\n  }\n\n  .thread {\n    box-shadow: none;\n  }\n}\n\n.switch__error {\n  font-size: 12px;\n  line-height: 16px;\n  color: var(--danger);\n}\n\n/* Review fixes: contrast, measure, orange scope, thread width, motion. */\n.composer__input::placeholder,\n.rail__you {\n  color: var(--gray-700);\n}\n\n.message__text {\n  max-width: 72ch;\n}\n\n.channel__switch .rail__hash {\n  color: var(--orange-dark);\n}\n\n.typing {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.typing__dots {\n  display: inline-flex;\n  gap: 2px;\n}\n\n.typing__dots .dot {\n  width: 6px;\n  height: 6px;\n}\n\n/* Less than ~280px of messages would be left beside the sheet: cover, and\n * take what it covers out of the tab order. */\n@container chat (max-width: 775px) {\n  .thread {\n    width: 100%;\n    border-left: 0;\n    box-shadow: none;\n  }\n\n  .channel:has(> .thread) > :not(.thread) {\n    visibility: hidden;\n  }\n}\n\n/* The signature moment: a person's dot arrives on the row they moved to. */\n@keyframes dot-arrive {\n  from {\n    transform: scale(0.2);\n    opacity: 0;\n  }\n}\n\n@keyframes dot-leave {\n  to {\n    transform: scale(0.2);\n    opacity: 0;\n  }\n}\n\n/* Only the channel rows' dots move: the online list is a list. */\n.rail__channel .dot,\n.typing__dots .dot {\n  animation: dot-arrive 0.36s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n.rail__channel .dot[data-leaving] {\n  animation: dot-leave 0.36s cubic-bezier(0.16, 1, 0.3, 1) forwards;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .rail__channel .dot,\n  .typing__dots .dot {\n    animation: none;\n  }\n\n  .rail__channel .dot[data-leaving] {\n    display: none;\n  }\n}\n"},{"isFile":true,"isOpen":false,"language":"tsx","name":"App.tsx","path":"/src/App.tsx","content":"import './App.css';\n\nimport { useCallback, useEffect, useMemo, useRef, useState } from 'react';\nimport {\n  type Document,\n  DocumentProvider,\n  SyncMode,\n  useDocument,\n  useYorkie,\n  YorkieProvider,\n} from '@yorkie-js/react';\nimport ExampleHeader, { type Status } from './ExampleHeader';\nimport ChannelRail from './ChannelRail';\nimport ChannelView from './ChannelView';\nimport {\n  channelKey,\n  type ChannelRoot,\n  type ChatPresence,\n  defaultChannels,\n  makeUser,\n  readChannels,\n  resolveIdentity,\n  roomPrefix,\n  seedRoot,\n  type WorkspaceRoot,\n} from './model';\n\n// One person per page load, made outside React so StrictMode's double render\n// does not make two.\nconst prefix = roomPrefix(window.location.search, new Date());\nconst initialPresence: ChatPresence = {\n  ...makeUser(),\n  channelId: 'general',\n  typing: false,\n};\n\n// \"Open another tab\" must land in this room even after midnight UTC, when a\n// fresh load would pick the next day's key.\nconst roomUrl = (() => {\n  const url = new URL(window.location.href);\n  url.searchParams.set('key', prefix);\n  return url.toString();\n})();\n\n/**\n * `App` connects to Yorkie and attaches the workspace document, which stays\n * attached for the whole session: its root is the channel list and its\n * presence is who is in which channel and who is typing.\n */\nexport default function App() {\n  return (\n    <YorkieProvider\n      apiKey={import.meta.env.VITE_YORKIE_API_KEY}\n      rpcAddr={import.meta.env.VITE_YORKIE_API_ADDR}\n    >\n      <DocumentProvider<WorkspaceRoot, ChatPresence>\n        docKey={prefix}\n        initialRoot={{ channels: defaultChannels } as WorkspaceRoot}\n        initialPresence={initialPresence}\n      >\n        <Workspace />\n      </DocumentProvider>\n    </YorkieProvider>\n  );\n}\n\nfunction Workspace() {\n  const { client } = useYorkie();\n  const {\n    doc: workspaceDoc,\n    root,\n    presences,\n    update,\n    connection,\n    loading,\n    error,\n  } = useDocument<WorkspaceRoot, ChatPresence>();\n  const [openId, setOpenId] = useState(initialPresence.channelId);\n  const [railOpen, setRailOpen] = useState(false);\n  const [offline, setOffline] = useState(false);\n  const [switching, setSwitching] = useState(false);\n  const [pendingIds, setPendingIds] = useState<Set<string>>(() => new Set());\n  const [channelReady, setChannelReady] = useState(false);\n  const [switchFailed, setSwitchFailed] = useState(false);\n  const [focusSwitch, setFocusSwitch] = useState(false);\n  const offlineRef = useRef(false);\n  const typing = useRef(false);\n  const channelDoc = useRef<Document<ChannelRoot> | undefined>(undefined);\n  const railTrigger = useRef<HTMLButtonElement | undefined>(undefined);\n\n  const people = useMemo(\n    () => presences.map(({ presence }) => presence),\n    [presences],\n  );\n  const me = useMemo<ChatPresence>(\n    () =>\n      people.find((p) => p.userId === initialPresence.userId) ?? {\n        ...initialPresence,\n        channelId: openId,\n      },\n    [people, openId],\n  );\n\n  // Whenever someone arrives: if we clash with someone who joined earlier,\n  // move to a free name and color. Panes opened together cannot see each\n  // other when they pick, so this cannot be done only once.\n  useEffect(() => {\n    if (loading || offline) return;\n    const others = people.filter((p) => p.userId !== me.userId);\n    const next = resolveIdentity(me, others);\n    if (next.name !== me.name || next.color !== me.color) {\n      update((_, presence) => presence.set(next));\n    }\n  }, [loading, offline, people, me, update]);\n\n  const closeRail = useCallback(() => {\n    setRailOpen(false);\n    railTrigger.current?.focus();\n  }, []);\n\n  const openChannel = useCallback(\n    (channelId: string) => {\n      if (channelId === openId) {\n        closeRail();\n        return;\n      }\n      // The trigger belongs to the channel view being replaced: the new one\n      // takes focus on its own channel button instead.\n      setFocusSwitch(railOpen);\n      setRailOpen(false);\n      setOpenId(channelId);\n      typing.current = false;\n      update((_, presence) => presence.set({ channelId, typing: false }));\n    },\n    [closeRail, openId, railOpen, update],\n  );\n\n  // Presence changes go to everyone, so only send the typing flag when it\n  // flips, not on every keystroke, and not at all while offline, where it\n  // would arrive late.\n  const setTyping = useCallback(\n    (next: boolean) => {\n      if (offlineRef.current || typing.current === next) return;\n      typing.current = next;\n      update((_, presence) => presence.set({ typing: next }));\n    },\n    [update],\n  );\n\n  const onWrite = useCallback((id: string) => {\n    if (offlineRef.current) setPendingIds((ids) => new Set(ids).add(id));\n  }, []);\n\n  const onDoc = useCallback((doc: Document<ChannelRoot> | undefined) => {\n    channelDoc.current = doc;\n    setChannelReady(!!doc);\n  }, []);\n\n  // Back online, marks come off once the channel's changes are actually\n  // pushed, which can be later than the switch when the server is slow.\n  useEffect(() => {\n    const ch = channelDoc.current;\n    if (offline || pendingIds.size === 0 || !ch || !channelReady) return;\n    return ch.subscribe('sync', (event) => {\n      if (event.value === 'synced' && !ch.hasLocalChanges()) {\n        setPendingIds(new Set());\n      }\n    });\n  }, [offline, pendingIds, channelReady]);\n\n  /**\n   * Offline pauses both documents with `SyncMode.Manual`. That ends their\n   * watch streams, so the others see this pane leave and it sees only itself;\n   * what it writes meanwhile waits locally. Back online, both resume\n   * `Realtime` and the waiting changes are pushed.\n   */\n  const toggleOffline = async () => {\n    const ch = channelDoc.current;\n    const ws = workspaceDoc;\n    if (!client || !ch || !ws) return;\n    setSwitching(true);\n    setSwitchFailed(false);\n    if (!offlineRef.current) {\n      // From here on, write as if offline: no typing flags, and what is sent\n      // is marked until it is pushed.\n      offlineRef.current = true;\n      try {\n        // Clear \"is typing\" first, while the others can still hear it.\n        typing.current = false;\n        update((_, presence) => presence.set({ typing: false }));\n        await client.sync(ws);\n        await client.changeSyncMode(ch, SyncMode.Manual);\n        await client.changeSyncMode(ws, SyncMode.Manual);\n        setOffline(true);\n      } catch (err) {\n        console.error('Could not go offline', err);\n        offlineRef.current = false;\n        setSwitchFailed(true);\n        await Promise.allSettled([\n          client.changeSyncMode(ch, SyncMode.Realtime),\n          client.changeSyncMode(ws, SyncMode.Realtime),\n        ]);\n      }\n    } else {\n      try {\n        await client.changeSyncMode(ch, SyncMode.Realtime);\n        await client.changeSyncMode(ws, SyncMode.Realtime);\n      } catch (err) {\n        // Stay offline as a whole rather than half online.\n        console.error('Could not go online', err);\n        setSwitchFailed(true);\n        await Promise.allSettled([\n          client.changeSyncMode(ch, SyncMode.Manual),\n          client.changeSyncMode(ws, SyncMode.Manual),\n        ]);\n        setSwitching(false);\n        return;\n      }\n      offlineRef.current = false;\n      setOffline(false);\n      // Realtime pushes what waited; this sync only tells us when. If it\n      // fails, the marks stay until a later sync succeeds (effect above).\n      const [pushed] = await Promise.allSettled([\n        client.sync(ch),\n        client.sync(ws),\n      ]);\n      if (pushed.status === 'fulfilled' && !ch.hasLocalChanges()) {\n        setPendingIds(new Set());\n      }\n    }\n    setSwitching(false);\n  };\n\n  const channels = useMemo(() => readChannels(root.channels), [root.channels]);\n  const channel = channels.find((c) => c.id === openId) ?? channels[0];\n  const channelSeed = useMemo(\n    () => seedRoot(channel.id, new Date()),\n    [channel.id],\n  );\n\n  let status: Status = 'offline';\n  if (error) status = 'error';\n  else if (loading) status = 'connecting';\n  else if (offline) status = 'offline';\n  else if (connection === 'connected') status = 'connected';\n\n  return (\n    <div className=\"chat\">\n      <ExampleHeader title=\"React Chat\" status={status} href={roomUrl}>\n        {!loading && !error && (\n          <button\n            type=\"button\"\n            className=\"switch\"\n            data-online={!offline || undefined}\n            disabled={switching || !channelReady}\n            title={\n              !channelReady && !switching\n                ? 'Wait for the channel to open'\n                : undefined\n            }\n            onClick={toggleOffline}\n          >\n            <span className=\"switch__track\" aria-hidden=\"true\">\n              <span className=\"switch__thumb\" />\n            </span>\n            {offline ? 'Go online' : 'Go offline'}\n          </button>\n        )}\n        {switchFailed && (\n          <span className=\"switch__error\" role=\"alert\">\n            Couldn&rsquo;t switch. Try again.\n          </span>\n        )}\n      </ExampleHeader>\n      {error ? (\n        <p className=\"state-message\" role=\"alert\">\n          Couldn&rsquo;t reach the Yorkie server at{' '}\n          {import.meta.env.VITE_YORKIE_API_ADDR}. Check that it&rsquo;s running,\n          then reload.\n        </p>\n      ) : loading ? (\n        <p className=\"state-message\">Joining the workspace…</p>\n      ) : (\n        <div className=\"chat__body\" data-rail-open={railOpen || undefined}>\n          <ChannelRail\n            channels={channels}\n            people={people}\n            me={me}\n            openId={openId}\n            onOpen={openChannel}\n            offline={offline}\n            busy={switching || !channelReady}\n            open={railOpen}\n            onClose={closeRail}\n          />\n          {railOpen && (\n            <button\n              type=\"button\"\n              className=\"scrim\"\n              aria-label=\"Close channels\"\n              tabIndex={-1}\n              onClick={closeRail}\n            />\n          )}\n          <DocumentProvider<ChannelRoot>\n            key={channel.id}\n            docKey={channelKey(prefix, channel.id)}\n            initialRoot={channelSeed}\n            disablePresence\n          >\n            <ChannelView\n              channel={channel}\n              me={me}\n              people={people}\n              offline={offline}\n              switching={switching}\n              focusSwitch={focusSwitch}\n              pendingIds={pendingIds}\n              setTyping={setTyping}\n              onWrite={onWrite}\n              onDoc={onDoc}\n              onShowChannels={(trigger) => {\n                railTrigger.current = trigger;\n                setRailOpen(true);\n              }}\n            />\n          </DocumentProvider>\n        </div>\n      )}\n    </div>\n  );\n}\n"},{"isFile":true,"isOpen":false,"language":"tsx","name":"ChannelRail.tsx","path":"/src/ChannelRail.tsx","content":"import { useEffect, useRef, useState } from 'react';\nimport type { ChannelInfo, ChatPresence } from './model';\n\ntype Props = {\n  channels: Array<ChannelInfo>;\n  people: Array<ChatPresence>;\n  me: ChatPresence;\n  openId: string;\n  onOpen: (channelId: string) => void;\n  /**\n   * Switching needs the server, so it is off while the pane is offline. The\n   * others cannot be seen either, so the online list says why.\n   */\n  offline: boolean;\n  /**\n   * Switching is also held while a channel is still opening or the pane is\n   * going on or offline: leaving a channel mid-attach would leave it attached.\n   */\n  busy: boolean;\n  /** Narrow panes show the rail over the channel; `open` moves focus into it. */\n  open: boolean;\n  onClose: () => void;\n};\n\nconst leaveMs = 360;\n\ntype Leaving = { key: string; channelId: string; color: ChatPresence['color'] };\n\n/**\n * `useLeavingDots` keeps a dot on the row someone just left (moved channel or\n * went away) for one exit animation, so the move reads as a move and not a\n * jump cut.\n */\nfunction useLeavingDots(people: Array<ChatPresence>): Array<Leaving> {\n  const before = useRef<Map<string, ChatPresence>>(new Map());\n  const timers = useRef<Set<ReturnType<typeof setTimeout>>>(new Set());\n  const [leaving, setLeaving] = useState<Array<Leaving>>([]);\n\n  useEffect(() => {\n    const now = new Map(people.map((p) => [p.userId, p]));\n    const gone: Array<Leaving> = [];\n    for (const [id, p] of before.current) {\n      if (now.get(id)?.channelId !== p.channelId) {\n        gone.push({\n          key: `${id}-${p.channelId}-${Date.now()}`,\n          channelId: p.channelId,\n          color: p.color,\n        });\n      }\n    }\n    before.current = now;\n    if (!gone.length) return;\n    // Show the ghosts, then drop them after one exit. Neither timer is\n    // cancelled by the next presence change, so a burst keeps every ghost.\n    const later = (fn: () => void, ms: number) => {\n      const t = setTimeout(() => {\n        timers.current.delete(t);\n        fn();\n      }, ms);\n      timers.current.add(t);\n    };\n    later(() => setLeaving((l) => [...l, ...gone]), 0);\n    later(() => setLeaving((l) => l.filter((x) => !gone.includes(x))), leaveMs);\n  }, [people]);\n\n  useEffect(() => {\n    const pending = timers.current;\n    return () => pending.forEach(clearTimeout);\n  }, []);\n\n  return leaving;\n}\n\nfunction names(list: Array<ChatPresence>): string {\n  return list.map((p) => p.name).join(', ');\n}\n\n/**\n * `ChannelRail` lists the channels with a dot for each person in them right\n * now, then who is online. Both come from the workspace document's presence.\n */\nexport default function ChannelRail({\n  channels,\n  people,\n  me,\n  openId,\n  onOpen,\n  offline,\n  busy,\n  open: shown,\n  onClose,\n}: Props) {\n  const rail = useRef<HTMLElement>(null);\n  const leaving = useLeavingDots(people);\n\n  useEffect(() => {\n    if (shown) {\n      rail.current\n        ?.querySelector<HTMLElement>('button:not(:disabled)')\n        ?.focus();\n    }\n  }, [shown]);\n\n  return (\n    <nav\n      ref={rail}\n      className=\"rail\"\n      aria-label=\"Channels\"\n      onKeyDown={(e) => shown && e.key === 'Escape' && onClose()}\n    >\n      <h2 className=\"rail__heading\">Channels</h2>\n      <ul className=\"rail__list\">\n        {channels.map((channel) => {\n          const here = people.filter((p) => p.channelId === channel.id);\n          const open = channel.id === openId;\n          return (\n            <li key={channel.id}>\n              <button\n                type=\"button\"\n                className=\"rail__channel\"\n                aria-current={open ? 'page' : undefined}\n                disabled={(offline || busy) && !open}\n                title={\n                  offline && !open ? 'Go online to switch channels' : undefined\n                }\n                onClick={() => onOpen(channel.id)}\n              >\n                <span className=\"rail__name\">\n                  <span className=\"rail__hash\" aria-hidden=\"true\">\n                    #\n                  </span>\n                  {channel.name}\n                </span>\n                <span\n                  className=\"dots\"\n                  role=\"img\"\n                  aria-label={\n                    here.length ? `Here: ${names(here)}` : 'Nobody here'\n                  }\n                >\n                  {here.map((p) => (\n                    <span\n                      key={p.userId}\n                      className=\"dot\"\n                      data-color={p.color}\n                      title={p.name}\n                    />\n                  ))}\n                  {leaving\n                    .filter((l) => l.channelId === channel.id)\n                    .map((l) => (\n                      <span\n                        key={l.key}\n                        className=\"dot\"\n                        data-color={l.color}\n                        data-leaving=\"\"\n                      />\n                    ))}\n                </span>\n              </button>\n            </li>\n          );\n        })}\n      </ul>\n\n      <h2 className=\"rail__heading\">\n        {offline ? 'Online' : `Online · ${people.length}`}\n      </h2>\n      {offline ? (\n        <p className=\"rail__alone\">\n          You&rsquo;re offline. Others can&rsquo;t see you, and you can&rsquo;t\n          see them, until you go online.\n        </p>\n      ) : people.length <= 1 ? (\n        <p className=\"rail__alone\">\n          You&rsquo;re alone here. Open this page in another tab to chat with\n          yourself.\n        </p>\n      ) : (\n        <ul className=\"rail__list\">\n          {people.map((p) => (\n            <li key={p.userId} className=\"rail__person\">\n              <span className=\"dot\" data-color={p.color} aria-hidden=\"true\" />\n              <span className=\"rail__person-name\">\n                {p.name}\n                {p.userId === me.userId && (\n                  <span className=\"rail__you\"> (you)</span>\n                )}\n              </span>\n            </li>\n          ))}\n        </ul>\n      )}\n    </nav>\n  );\n}\n"},{"isFile":true,"isOpen":false,"language":"tsx","name":"ChannelView.tsx","path":"/src/ChannelView.tsx","content":"import { useEffect, useRef, useState } from 'react';\nimport { type Document, useDocument } from '@yorkie-js/react';\nimport Composer from './Composer';\nimport { ChevronIcon } from './icons';\nimport MessageList from './MessageList';\nimport {\n  addMessage,\n  addReply,\n  type ChannelInfo,\n  type ChannelRoot,\n  type ChatPresence,\n  emptyReactions,\n  type Message,\n  newId,\n  readMessages,\n  toggleReaction,\n} from './model';\nimport ThreadSheet from './ThreadSheet';\n\ntype Props = {\n  channel: ChannelInfo;\n  me: ChatPresence;\n  people: Array<ChatPresence>;\n  offline: boolean;\n  /** Going on or offline: hold the box so nothing lands mid-switch. */\n  switching: boolean;\n  /** Take focus on the channel button: the rail it was opened from closed. */\n  focusSwitch: boolean;\n  pendingIds: Set<string>;\n  setTyping: (typing: boolean) => void;\n  /** Called with each id this pane writes, so it can be marked while offline. */\n  onWrite: (id: string) => void;\n  /** Hands the channel document up once attached, for the offline switch. */\n  onDoc: (doc: Document<ChannelRoot> | undefined) => void;\n  onShowChannels: (trigger: HTMLButtonElement) => void;\n};\n\nfunction typingLine(names: Array<string>): string {\n  if (names.length === 1) return `${names[0]} is typing…`;\n  if (names.length === 2) return `${names[0]} and ${names[1]} are typing…`;\n  return 'Several people are typing…';\n}\n\n/**\n * `ChannelView` is the open channel: its document's messages, the typing\n * line from the workspace presence, the message box and the thread sheet.\n */\nexport default function ChannelView({\n  channel,\n  me,\n  people,\n  offline,\n  switching,\n  focusSwitch,\n  pendingIds,\n  setTyping,\n  onWrite,\n  onDoc,\n  onShowChannels,\n}: Props) {\n  const { doc, root, update, loading, error } = useDocument<ChannelRoot>();\n  const [threadId, setThreadId] = useState<string | undefined>(undefined);\n  const threadTrigger = useRef<HTMLButtonElement | undefined>(undefined);\n  const switchButton = useRef<HTMLButtonElement>(null);\n  const ready = !!doc && !loading && !error;\n\n  useEffect(() => {\n    onDoc(ready ? doc : undefined);\n    return () => onDoc(undefined);\n  }, [ready, doc, onDoc]);\n\n  useEffect(() => {\n    if (focusSwitch) switchButton.current?.focus();\n    // Only on mount: this view is keyed by channel.\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const here = people.filter((p) => p.channelId === channel.id);\n  const typers = here.filter((p) => p.typing && p.userId !== me.userId);\n  // Read through `readMessages`: in a public room `messages` itself may be\n  // anything, not only the messages in it.\n  const messages = readMessages(root.messages);\n  const thread = threadId ? messages.find((m) => m.id === threadId) : undefined;\n\n  // If the thread's message goes away under it (trimmed past the cap by\n  // someone else), `thread` is undefined and the sheet simply closes.\n\n  const author = () => ({\n    id: newId(),\n    userId: me.userId,\n    name: me.name,\n    color: me.color,\n    at: new Date().toISOString(),\n  });\n\n  const send = (text: string) => {\n    const m: Message = {\n      ...author(),\n      text,\n      reactions: emptyReactions(),\n      replies: [],\n    };\n    update((root) => addMessage(root, m));\n    onWrite(m.id);\n  };\n\n  const reply = (text: string) => {\n    if (!threadId) return;\n    const r = { ...author(), text };\n    update((root) => addReply(root, threadId, r));\n    onWrite(r.id);\n  };\n\n  // Focus goes back to the thread's trigger only after the sheet is gone:\n  // in narrow panes the sheet hides what it covers, the trigger included,\n  // so focusing it in the click handler would do nothing.\n  const restoreFocus = useRef(false);\n  useEffect(() => {\n    if (threadId || !restoreFocus.current) return;\n    restoreFocus.current = false;\n    threadTrigger.current?.focus();\n  }, [threadId]);\n\n  const closeThread = () => {\n    restoreFocus.current = true;\n    setThreadId(undefined);\n  };\n\n  return (\n    <main className=\"channel\" aria-label={`#${channel.name}`}>\n      <div className=\"channel__head\">\n        <button\n          ref={switchButton}\n          type=\"button\"\n          className=\"channel__switch\"\n          aria-label={`#${channel.name}, show channels`}\n          onClick={(e) => onShowChannels(e.currentTarget)}\n        >\n          <span className=\"rail__hash\" aria-hidden=\"true\">\n            #\n          </span>\n          {channel.name}\n          <ChevronIcon />\n        </button>\n        <h2 className=\"channel__title\">\n          <span className=\"rail__hash\" aria-hidden=\"true\">\n            #\n          </span>\n          {channel.name}\n        </h2>\n        <p className=\"channel__here\">\n          {offline ? 'Offline' : `${here.length} here now`}\n        </p>\n      </div>\n\n      {error ? (\n        <p className=\"state-message\" role=\"alert\">\n          Couldn&rsquo;t open #{channel.name}. Reload to try again.\n        </p>\n      ) : loading ? (\n        <p className=\"state-message\">Opening #{channel.name}…</p>\n      ) : messages.length === 0 ? (\n        <p className=\"state-message\">No messages yet. Say hello.</p>\n      ) : (\n        <MessageList\n          messages={messages}\n          me={me}\n          pendingIds={pendingIds}\n          onReact={(id, emoji) =>\n            update((root) => toggleReaction(root, id, emoji, me.userId))\n          }\n          onOpenThread={(id, trigger) => {\n            threadTrigger.current = trigger;\n            setThreadId(id);\n          }}\n        />\n      )}\n\n      <p className=\"typing\" aria-live=\"polite\">\n        {typers.length > 0 && (\n          <>\n            <span className=\"typing__dots\" aria-hidden=\"true\">\n              {typers.slice(0, 3).map((p) => (\n                <span key={p.userId} className=\"dot\" data-color={p.color} />\n              ))}\n            </span>\n            {typingLine(typers.map((p) => p.name))}\n          </>\n        )}\n      </p>\n      <Composer\n        label={`Message #${channel.name}`}\n        placeholder={\n          ready ? `Message #${channel.name}` : `Opening #${channel.name}…`\n        }\n        onSend={send}\n        onTyping={setTyping}\n        disabled={!ready || switching}\n      />\n\n      {thread && (\n        <ThreadSheet\n          key={thread.id}\n          message={thread}\n          pendingIds={pendingIds}\n          onReply={reply}\n          onClose={closeThread}\n        />\n      )}\n    </main>\n  );\n}\n"},{"isFile":true,"isOpen":false,"language":"tsx","name":"Composer.tsx","path":"/src/Composer.tsx","content":"import { useEffect, useRef, useState, type KeyboardEvent } from 'react';\nimport { SendIcon } from './icons';\nimport { normalizeText, textMax, toSendable } from './model';\n\nconst idleMs = 3000;\nconst counterFrom = textMax - 50;\n\ntype Props = {\n  label: string;\n  placeholder: string;\n  onSend: (text: string) => void;\n  /** Called with `true` while there is text being written, `false` after. */\n  onTyping?: (typing: boolean) => void;\n  autoFocus?: boolean;\n  /** Off until the document is attached: a write before that goes nowhere. */\n  disabled?: boolean;\n};\n\n/**\n * `Composer` is the message box. Enter sends, Shift+Enter starts a new line,\n * and an Enter that ends an IME composition (Korean, Japanese, …) is left to\n * the IME.\n */\nexport default function Composer({\n  label,\n  placeholder,\n  onSend,\n  onTyping,\n  autoFocus,\n  disabled = false,\n}: Props) {\n  const [text, setText] = useState('');\n  const idle = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);\n  const box = useRef<HTMLTextAreaElement>(null);\n  // Count what would be sent, so pasted blanks do not block a message.\n  const normalized = normalizeText(text);\n  const clean = toSendable(normalized);\n  const length = [...normalized].length;\n  const tooLong = length > textMax;\n\n  const stopTyping = () => {\n    clearTimeout(idle.current);\n    onTyping?.(false);\n  };\n\n  useEffect(() => () => clearTimeout(idle.current), []);\n\n  // Grow with the text up to four lines, then scroll.\n  useEffect(() => {\n    const el = box.current;\n    if (!el) return;\n    el.style.height = 'auto';\n    el.style.height = `${Math.min(el.scrollHeight, 22 * 4 + 16)}px`;\n  }, [text]);\n\n  const change = (value: string) => {\n    setText(value);\n    if (!onTyping) return;\n    clearTimeout(idle.current);\n    if (normalizeText(value)) {\n      onTyping(true);\n      idle.current = setTimeout(() => onTyping(false), idleMs);\n    } else {\n      onTyping(false);\n    }\n  };\n\n  const send = () => {\n    if (!clean || tooLong || disabled) return;\n    onSend(clean);\n    setText('');\n    stopTyping();\n  };\n\n  const keyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {\n    if (e.key !== 'Enter' || e.shiftKey) return;\n    if (e.nativeEvent.isComposing || e.keyCode === 229) return;\n    e.preventDefault();\n    send();\n  };\n\n  return (\n    <form\n      className=\"composer\"\n      onSubmit={(e) => {\n        e.preventDefault();\n        send();\n      }}\n    >\n      <textarea\n        ref={box}\n        className=\"composer__input\"\n        rows={1}\n        aria-label={label}\n        placeholder={placeholder}\n        value={text}\n        autoFocus={autoFocus}\n        disabled={disabled}\n        onChange={(e) => change(e.target.value)}\n        onKeyDown={keyDown}\n        onBlur={onTyping ? stopTyping : undefined}\n      />\n      {length >= counterFrom && (\n        <span\n          className=\"composer__count\"\n          data-over={tooLong || undefined}\n          aria-live=\"polite\"\n        >\n          {length}/{textMax}\n        </span>\n      )}\n      <button\n        type=\"submit\"\n        className=\"composer__send\"\n        aria-label=\"Send\"\n        disabled={!clean || tooLong || disabled}\n      >\n        <SendIcon />\n      </button>\n    </form>\n  );\n}\n"},{"isFile":true,"isOpen":false,"language":"tsx","name":"ExampleHeader.tsx","path":"/src/ExampleHeader.tsx","content":"import type { ReactNode } from 'react';\n\nexport type Status = 'connecting' | 'connected' | 'offline' | 'error';\n\nconst statusLabels: Record<Status, string> = {\n  connecting: 'Connecting…',\n  connected: 'Connected',\n  offline: 'Offline',\n  error: 'Error',\n};\n\ninterface ExampleHeaderProps {\n  title: string;\n  status: Status;\n  /** Where \"another tab\" leads; defaults to this page. */\n  href?: string;\n  children?: ReactNode;\n}\n\n/**\n * `ExampleHeader` shows the example name, how to try it and the connection\n * status. The \"another tab\" link opens this same URL, so the second client\n * attaches to the same document.\n */\nexport default function ExampleHeader({\n  title,\n  status,\n  href = window.location.href,\n  children,\n}: ExampleHeaderProps) {\n  return (\n    <header className=\"example-header\">\n      <div className=\"example-header__intro\">\n        <p className=\"example-header__title\">{title}</p>\n        <p className=\"example-header__hint\">\n          Chat with yourself — open this page in{' '}\n          <a href={href} target=\"_blank\" rel=\"noreferrer\">\n            another tab\n          </a>{' '}\n          to see messages sync.\n        </p>\n      </div>\n      <div className=\"example-header__meta\">\n        <span className=\"status\" data-status={status}>\n          <span className=\"status__dot\" aria-hidden=\"true\" />\n          {statusLabels[status]}\n        </span>\n        {children}\n      </div>\n    </header>\n  );\n}\n"},{"isFile":true,"isOpen":false,"language":"tsx","name":"MessageList.tsx","path":"/src/MessageList.tsx","content":"import { useLayoutEffect, useRef, useState } from 'react';\nimport { ReactIcon } from './icons';\nimport {\n  type ChatPresence,\n  emojis,\n  type Message,\n  reactionCount,\n  type Reply,\n} from './model';\n\n// A message from the same person within this long of the one before it is\n// drawn without its avatar and name, as chat apps do.\nconst groupMs = 5 * 60 * 1000;\n\nconst time = (at: string) =>\n  at\n    ? new Date(at).toLocaleTimeString([], {\n        hour: '2-digit',\n        minute: '2-digit',\n      })\n    : '';\n\nexport function Avatar({ person }: { person: Pick<Reply, 'name' | 'color'> }) {\n  return (\n    <span className=\"avatar\" data-color={person.color} aria-hidden=\"true\">\n      {[...person.name][0]}\n    </span>\n  );\n}\n\n/** `MessageBody` is a message's name line and text, shared with the thread. */\nexport function MessageBody({\n  message,\n  pending,\n  compact = false,\n}: {\n  message: Reply;\n  pending: boolean;\n  compact?: boolean;\n}) {\n  return (\n    <>\n      {!compact && (\n        <p className=\"message__meta\">\n          <span className=\"message__name\">{message.name}</span>\n          {message.at && (\n            <time className=\"message__time\" dateTime={message.at}>\n              {time(message.at)}\n            </time>\n          )}\n        </p>\n      )}\n      <p className=\"message__text\">{message.text}</p>\n      {pending && <p className=\"message__pending\">Not sent yet</p>}\n    </>\n  );\n}\n\ntype Props = {\n  /** Already read through `readMessages`. */\n  messages: Array<Message>;\n  me: ChatPresence;\n  pendingIds: Set<string>;\n  onReact: (messageId: string, emoji: string) => void;\n  onOpenThread: (messageId: string, trigger: HTMLButtonElement) => void;\n};\n\n/**\n * `MessageList` draws the channel's messages, keeping the view pinned to the\n * newest one unless the reader has scrolled up.\n */\nexport default function MessageList({\n  messages,\n  me,\n  pendingIds,\n  onReact,\n  onOpenThread,\n}: Props) {\n  const list = useRef<HTMLOListElement>(null);\n  const pinned = useRef(true);\n  const pickerTrigger = useRef<HTMLButtonElement | undefined>(undefined);\n  const [pickerFor, setPickerFor] = useState<string | undefined>(undefined);\n  // Keyed on the newest message, not the count: at the cap a new message\n  // replaces the oldest and the count stays the same.\n  const newest = messages.length ? messages[messages.length - 1].id : '';\n  useLayoutEffect(() => {\n    const el = list.current;\n    if (el && pinned.current) el.scrollTop = el.scrollHeight;\n  }, [newest]);\n\n  const closePicker = () => {\n    setPickerFor(undefined);\n    pickerTrigger.current?.focus();\n  };\n\n  return (\n    <ol\n      ref={list}\n      className=\"messages\"\n      aria-label=\"Messages\"\n      onScroll={(e) => {\n        const el = e.currentTarget;\n        pinned.current = el.scrollHeight - el.scrollTop - el.clientHeight < 24;\n      }}\n    >\n      {messages.map((m, i) => {\n        const prev = i > 0 ? messages[i - 1] : undefined;\n        const compact =\n          !!prev &&\n          prev.userId === m.userId &&\n          !!m.at &&\n          !!prev.at &&\n          Date.parse(m.at) - Date.parse(prev.at) < groupMs;\n        const used = Object.keys(m.reactions).filter(\n          (emoji) => reactionCount(m.reactions[emoji]) > 0,\n        );\n        const replies = m.replies.length;\n        return (\n          <li\n            key={m.id}\n            className=\"message\"\n            data-compact={compact || undefined}\n          >\n            {compact ? <span className=\"avatar-gap\" /> : <Avatar person={m} />}\n            <div className=\"message__main\">\n              <MessageBody\n                message={m}\n                pending={pendingIds.has(m.id)}\n                compact={compact}\n              />\n              {(used.length > 0 || replies > 0) && (\n                <div className=\"message__extras\">\n                  {used.map((emoji) => {\n                    const people = m.reactions[emoji];\n                    const mine = !!people[me.userId];\n                    const count = reactionCount(people);\n                    return (\n                      <button\n                        key={emoji}\n                        type=\"button\"\n                        className=\"reaction\"\n                        data-color={mine ? me.color : undefined}\n                        aria-pressed={mine}\n                        aria-label={`${emoji} ${count} ${count === 1 ? 'person' : 'people'}${mine ? ', including you' : ''}`}\n                        onClick={() => onReact(m.id, emoji)}\n                      >\n                        <span aria-hidden=\"true\">{emoji}</span>\n                        <span className=\"reaction__count\">{count}</span>\n                      </button>\n                    );\n                  })}\n                  {replies > 0 && (\n                    <button\n                      type=\"button\"\n                      className=\"message__replies\"\n                      onClick={(e) => onOpenThread(m.id, e.currentTarget)}\n                    >\n                      {replies} {replies === 1 ? 'reply' : 'replies'}\n                    </button>\n                  )}\n                </div>\n              )}\n              {pickerFor === m.id && (\n                <div\n                  className=\"picker\"\n                  role=\"group\"\n                  aria-label=\"Add a reaction\"\n                  onKeyDown={(e) => e.key === 'Escape' && closePicker()}\n                >\n                  {emojis.map((emoji, j) => (\n                    <button\n                      key={emoji}\n                      type=\"button\"\n                      className=\"picker__emoji\"\n                      autoFocus={j === 0}\n                      aria-label={`React with ${emoji}`}\n                      onClick={() => {\n                        onReact(m.id, emoji);\n                        closePicker();\n                      }}\n                    >\n                      {emoji}\n                    </button>\n                  ))}\n                </div>\n              )}\n            </div>\n            <div className=\"message__actions\">\n              <button\n                type=\"button\"\n                className=\"icon-button\"\n                aria-label=\"Add a reaction\"\n                aria-expanded={pickerFor === m.id}\n                title=\"Add a reaction\"\n                onClick={(e) => {\n                  pickerTrigger.current = e.currentTarget;\n                  setPickerFor(pickerFor === m.id ? undefined : m.id);\n                }}\n              >\n                <ReactIcon />\n              </button>\n              <button\n                type=\"button\"\n                className=\"text-button\"\n                onClick={(e) => onOpenThread(m.id, e.currentTarget)}\n              >\n                Reply\n              </button>\n            </div>\n          </li>\n        );\n      })}\n    </ol>\n  );\n}\n"},{"isFile":true,"isOpen":false,"language":"tsx","name":"ThreadSheet.tsx","path":"/src/ThreadSheet.tsx","content":"import { useEffect, useRef } from 'react';\nimport Composer from './Composer';\nimport { CloseIcon } from './icons';\nimport { Avatar, MessageBody } from './MessageList';\nimport type { Message } from './model';\n\ntype Props = {\n  message: Message;\n  pendingIds: Set<string>;\n  onReply: (text: string) => void;\n  onClose: () => void;\n};\n\n/**\n * `ThreadSheet` is a message's thread, over the message column: the message\n * on top, its replies, and a reply box.\n */\nexport default function ThreadSheet({\n  message,\n  pendingIds,\n  onReply,\n  onClose,\n}: Props) {\n  const list = useRef<HTMLOListElement>(null);\n\n  useEffect(() => {\n    const el = list.current;\n    if (el) el.scrollTop = el.scrollHeight;\n  }, [message.replies.length]);\n\n  return (\n    <aside\n      className=\"thread\"\n      aria-label={`Thread on ${message.name}'s message`}\n      onKeyDown={(e) => e.key === 'Escape' && onClose()}\n    >\n      <div className=\"thread__head\">\n        <h2 className=\"thread__title\">Thread</h2>\n        <button\n          type=\"button\"\n          className=\"icon-button\"\n          aria-label=\"Close thread\"\n          onClick={onClose}\n        >\n          <CloseIcon />\n        </button>\n      </div>\n      <ol ref={list} className=\"messages thread__messages\">\n        <li className=\"message thread__parent\">\n          <Avatar person={message} />\n          <div className=\"message__main\">\n            <MessageBody\n              message={message}\n              pending={pendingIds.has(message.id)}\n            />\n          </div>\n        </li>\n        <li className=\"thread__count\">\n          {message.replies.length === 0\n            ? 'No replies yet'\n            : `${message.replies.length} ${message.replies.length === 1 ? 'reply' : 'replies'}`}\n        </li>\n        {message.replies.map((r) => (\n          <li key={r.id} className=\"message\">\n            <Avatar person={r} />\n            <div className=\"message__main\">\n              <MessageBody message={r} pending={pendingIds.has(r.id)} />\n            </div>\n          </li>\n        ))}\n      </ol>\n      <Composer label=\"Reply\" placeholder=\"Reply…\" onSend={onReply} autoFocus />\n    </aside>\n  );\n}\n"},{"isFile":true,"isOpen":false,"language":"tsx","name":"icons.tsx","path":"/src/icons.tsx","content":"import type { SVGProps } from 'react';\n\n// Icons drawn in one 1.5px stroke on a 16px grid, colored by `currentColor`.\nconst base: SVGProps<SVGSVGElement> = {\n  width: 16,\n  height: 16,\n  viewBox: '0 0 16 16',\n  fill: 'none',\n  stroke: 'currentColor',\n  strokeWidth: 1.5,\n  strokeLinecap: 'round',\n  strokeLinejoin: 'round',\n  'aria-hidden': true,\n  focusable: false,\n};\n\nexport function CloseIcon() {\n  return (\n    <svg {...base}>\n      <path d=\"M4 4l8 8M12 4l-8 8\" />\n    </svg>\n  );\n}\n\nexport function ReactIcon() {\n  return (\n    <svg {...base}>\n      <path d=\"M13.9 7.2A6 6 0 1 1 8.8 2.1\" />\n      <path d=\"M5.5 9.5c.6.9 1.5 1.4 2.5 1.4s1.9-.5 2.5-1.4\" />\n      <path d=\"M6 6.2v.1M10 6.2v.1\" />\n      <path d=\"M12.5 1.5v4M10.5 3.5h4\" />\n    </svg>\n  );\n}\n\nexport function ChevronIcon() {\n  return (\n    <svg {...base}>\n      <path d=\"M4.5 6.5L8 10l3.5-3.5\" />\n    </svg>\n  );\n}\n\nexport function SendIcon() {\n  return (\n    <svg {...base}>\n      <path d=\"M2.5 8h9M8 4.5L11.5 8 8 11.5\" />\n    </svg>\n  );\n}\n"},{"isFile":true,"isOpen":false,"language":"tsx","name":"main.tsx","path":"/src/main.tsx","content":"import ReactDOM from 'react-dom/client';\nimport App from './App';\nimport { StrictMode } from 'react';\n\nReactDOM.createRoot(document.getElementById('root') as HTMLElement).render(\n  <StrictMode>\n    <App />\n  </StrictMode>,\n);\n"},{"isFile":true,"isOpen":false,"language":"typescript","name":"merge.test.ts","path":"/src/merge.test.ts","content":"import { describe, expect, it } from 'vitest';\nimport { Document } from '@yorkie-js/sdk/src/document/document';\nimport { OpSource } from '@yorkie-js/sdk/src/document/operation/operation';\nimport { type ChannelRoot, seedRoot, toggleReaction } from './model';\n\n// Two replicas exchanging changes directly, without a server, the way the\n// SDK's own unit tests do: what each pane would end up with after sync.\nfunction replicas() {\n  const a = new Document<ChannelRoot>('merge');\n  const b = new Document<ChannelRoot>('merge');\n  a.setActor('000000000000000000000001');\n  b.setActor('000000000000000000000002');\n  const sent = new Map<Document<ChannelRoot>, number>();\n  const send = (from: Document<ChannelRoot>, to: Document<ChannelRoot>) => {\n    const changes = from.createChangePack().getChanges();\n    to.applyChanges(changes.slice(sent.get(from) ?? 0), OpSource.Remote);\n    sent.set(from, changes.length);\n  };\n  a.update((root) => {\n    root.messages = seedRoot('general', new Date()).messages;\n  });\n  send(a, b);\n  return { a, b, sync: () => (send(a, b), send(b, a)) };\n}\n\nconst count = (doc: Document<ChannelRoot>) =>\n  Object.keys(doc.getRoot().messages[0].reactions['👍']).length;\n\ndescribe('reactions across two panes', () => {\n  it('counts two first reactions made at the same time', () => {\n    const { a, b, sync } = replicas();\n    a.update((root) => toggleReaction(root, 'seed-general', '👍', 'ari'));\n    b.update((root) => toggleReaction(root, 'seed-general', '👍', 'ben'));\n    sync();\n    expect(count(a)).toBe(2);\n    expect(count(b)).toBe(2);\n  });\n\n  it('keeps a reaction added while another is removed', () => {\n    const { a, b, sync } = replicas();\n    a.update((root) => toggleReaction(root, 'seed-general', '👍', 'ari'));\n    sync();\n    a.update((root) => toggleReaction(root, 'seed-general', '👍', 'ari'));\n    b.update((root) => toggleReaction(root, 'seed-general', '👍', 'ben'));\n    sync();\n    expect(a.getRoot().messages[0].reactions['👍']).toEqual({ ben: true });\n    expect(b.getRoot().messages[0].reactions['👍']).toEqual({ ben: true });\n  });\n});\n"},{"isFile":true,"isOpen":false,"language":"typescript","name":"model.test.ts","path":"/src/model.test.ts","content":"import { describe, expect, it } from 'vitest';\nimport { Document, type JSONArray } from '@yorkie-js/sdk';\nimport {\n  addMessage,\n  addReply,\n  channelKey,\n  emptyReactions,\n  type ChannelRoot,\n  type ChatPresence,\n  cleanText,\n  defaultChannels,\n  makeUser,\n  type Message,\n  messagesMax,\n  newId,\n  normalizeText,\n  readChannels,\n  readMessage,\n  readMessages,\n  type PeerColor,\n  resolveIdentity,\n  roomPrefix,\n  seedRoot,\n  toggleReaction,\n} from './model';\n\nconst now = new Date('2026-11-18T10:00:00Z');\n\nfunction message(id: string, text = id): Message {\n  return {\n    id,\n    userId: 'u1',\n    name: 'Ari',\n    color: 'blue',\n    text,\n    at: now.toISOString(),\n    reactions: emptyReactions(),\n    replies: [],\n  };\n}\n\nfunction channelDoc(): Document<ChannelRoot> {\n  const doc = new Document<ChannelRoot>('test-channel');\n  doc.update((root) => {\n    root.messages = [message('m1')] as JSONArray<Message>;\n  });\n  return doc;\n}\n\ndescribe('cleanText', () => {\n  it('strips control characters and collapses blanks', () => {\n    expect(cleanText('  a\\u0000b   c ')).toBe('ab c');\n  });\n\n  it('counts what would be sent before cutting', () => {\n    expect([\n      ...normalizeText(`${' '.repeat(400)}a${' \\n'.repeat(300)}`),\n    ]).toHaveLength(1);\n  });\n\n  it('turns tabs into spaces', () => {\n    expect(cleanText('a\\tb')).toBe('a b');\n  });\n\n  it('keeps compound emoji whole', () => {\n    expect(cleanText('👩‍💻 🏳️‍🌈')).toBe('👩‍💻 🏳️‍🌈');\n  });\n\n  it('keeps line breaks, at most one blank line', () => {\n    expect(cleanText('a \\n b\\n\\n\\n\\nc')).toBe('a\\nb\\n\\nc');\n  });\n\n  it('strips direction overrides', () => {\n    expect(cleanText('\\u202Ex')).toBe('x');\n  });\n\n  it('returns undefined for blank input', () => {\n    expect(cleanText('   ')).toBeUndefined();\n  });\n\n  it('keeps at most 500 code points', () => {\n    expect([...(cleanText('가'.repeat(600)) ?? '')]).toHaveLength(500);\n    expect([...(cleanText('😀'.repeat(600)) ?? '')]).toHaveLength(500);\n  });\n});\n\ndescribe('keys', () => {\n  it('uses the UTC date by default', () => {\n    expect(roomPrefix('', now)).toBe('react-chat-20261118');\n  });\n\n  it('lets ?key override the prefix', () => {\n    expect(roomPrefix('?key=team', now)).toBe('team');\n  });\n\n  it('suffixes the channel id', () => {\n    expect(channelKey('team', 'design')).toBe('team-design');\n  });\n});\n\ndescribe('newId', () => {\n  it('falls back when randomUUID is missing', () => {\n    const original = crypto.randomUUID;\n    Object.defineProperty(crypto, 'randomUUID', {\n      value: undefined,\n      configurable: true,\n    });\n    try {\n      const a = newId();\n      expect(a).toMatch(/^[a-z0-9]+-[a-z0-9]+$/);\n      expect(newId()).not.toBe(a);\n    } finally {\n      Object.defineProperty(crypto, 'randomUUID', {\n        value: original,\n        configurable: true,\n      });\n    }\n  });\n});\n\ndescribe('makeUser', () => {\n  it('picks from the person colors', () => {\n    expect(makeUser(() => 0).color).toBe('blue');\n  });\n\n  it('never picks orange', () => {\n    for (let i = 0; i < 100; i++) {\n      expect(makeUser().color).not.toBe('orange');\n    }\n  });\n});\n\ndescribe('resolveIdentity', () => {\n  const person = (\n    userId: string,\n    name: string,\n    color: PeerColor,\n    joinedAt = '2026-11-18T10:00:00.000Z',\n  ): ChatPresence => ({\n    userId,\n    name,\n    color,\n    joinedAt,\n    channelId: 'general',\n    typing: false,\n  });\n\n  it('keeps a free name and color', () => {\n    const me = person('b', 'Ari', 'blue');\n    expect(resolveIdentity(me, [person('a', 'Ben', 'green')])).toEqual({\n      name: 'Ari',\n      color: 'blue',\n    });\n  });\n\n  it('moves the later joiner off a clash', () => {\n    const early = person('z', 'Ari', 'blue', '2026-11-18T10:00:00.000Z');\n    const late = person('a', 'Ari', 'blue', '2026-11-18T10:00:01.000Z');\n    expect(resolveIdentity(early, [late])).toEqual({\n      name: 'Ari',\n      color: 'blue',\n    });\n    expect(resolveIdentity(late, [early])).toEqual({\n      name: 'Ben',\n      color: 'green',\n    });\n  });\n\n  it('breaks a tie by userId, so both panes agree', () => {\n    const a = person('a', 'Gus', 'yellow');\n    const b = person('b', 'Gus', 'blue');\n    expect(resolveIdentity(a, [b]).name).toBe('Gus');\n    expect(resolveIdentity(b, [a]).name).not.toBe('Gus');\n    expect(resolveIdentity(b, [a]).color).toBe('blue');\n  });\n\n  it('keeps its color when every color is taken', () => {\n    const others = (['blue', 'green', 'purple', 'yellow', 'red'] as const).map(\n      (color, i) => person(`0${i}`, `P${i}`, color),\n    );\n    expect(resolveIdentity(person('z', 'Ari', 'red'), others).color).toBe(\n      'red',\n    );\n  });\n});\n\ndescribe('readMessage', () => {\n  it('passes a well-formed message through', () => {\n    const m = message('m1');\n    expect(readMessage(m)).toEqual(m);\n  });\n\n  it('reads a message straight from a document', () => {\n    const doc = channelDoc();\n    const { id, userId, name, color, text, at } = message('r1');\n    doc.update((root) => {\n      addReply(root, 'm1', { id, userId, name, color, text, at });\n      toggleReaction(root, 'm1', '👍', 'u1');\n    });\n    const m = readMessage(doc.getRoot().messages[0]);\n    expect(m?.replies.map((r) => r.id)).toEqual(['r1']);\n    expect(m?.reactions['👍']).toEqual({ u1: true });\n  });\n\n  it('drops what cannot be drawn', () => {\n    expect(readMessage(undefined)).toBeUndefined();\n    expect(readMessage({ text: 'no id' })).toBeUndefined();\n  });\n\n  it('fills in missing or broken fields', () => {\n    const m = readMessage({ id: 'x', at: 1794928803603n, color: 'teal' });\n    expect(m).toMatchObject({\n      id: 'x',\n      text: '',\n      at: '',\n      color: 'blue',\n      reactions: {},\n      replies: [],\n    });\n  });\n});\n\ndescribe('remote text', () => {\n  it('cleans and caps text another client stored', () => {\n    const m = readMessage({ id: 'x', text: '\\u202E' + 'a'.repeat(900) });\n    expect([...(m?.text ?? '')]).toHaveLength(500);\n    expect(m?.text.startsWith('a')).toBe(true);\n  });\n});\n\ndescribe('readMessages', () => {\n  it('reads a stored list and skips bad entries', () => {\n    expect(readMessages([message('m1'), 3, {}]).map((m) => m.id)).toEqual([\n      'm1',\n    ]);\n  });\n\n  it('treats anything but a list as empty', () => {\n    expect(readMessages({})).toEqual([]);\n    expect(readMessages('x')).toEqual([]);\n  });\n});\n\ndescribe('reading a public room', () => {\n  it('keeps only the fixed emoji set', () => {\n    const m = readMessage({\n      ...message('x'),\n      reactions: {\n        '👍': { a: true },\n        ['\\u202E' + 'x'.repeat(50)]: { b: true },\n      },\n    });\n    expect(Object.keys(m?.reactions ?? {})).toEqual(['👍']);\n  });\n\n  it('drops messages and replies with a repeated id', () => {\n    const r = {\n      id: 'r',\n      userId: 'u',\n      name: 'A',\n      color: 'blue',\n      text: 't',\n      at: '',\n    };\n    const list = readMessages([\n      { ...message('m'), replies: [r, r] },\n      message('m'),\n    ]);\n    expect(list).toHaveLength(1);\n    expect(list[0].replies).toHaveLength(1);\n  });\n\n  it('skips writes to a malformed message instead of throwing', () => {\n    const doc = new Document<ChannelRoot>('test-bad');\n    doc.update((root) => {\n      root.messages = [{ id: 'bad' }] as unknown as JSONArray<Message>;\n    });\n    const { id, userId, name, color, text, at } = message('r1');\n    expect(() =>\n      doc.update((root) => {\n        toggleReaction(root, 'bad', '👍', 'u1');\n        addReply(root, 'bad', { id, userId, name, color, text, at });\n      }),\n    ).not.toThrow();\n  });\n});\n\ndescribe('readChannels', () => {\n  it('keeps usable channels', () => {\n    expect(readChannels([{ id: 'ops', name: 'ops' }])).toEqual([\n      { id: 'ops', name: 'ops' },\n    ]);\n  });\n\n  it('drops ids that cannot go into a key, and duplicates', () => {\n    expect(\n      readChannels([{ id: 'ok' }, { id: '../x' }, {}, { id: 'ok' }]),\n    ).toEqual([{ id: 'ok', name: 'ok' }]);\n  });\n\n  it('falls back to the default channels', () => {\n    expect(readChannels({})).toBe(defaultChannels);\n    expect(readChannels([{}])).toBe(defaultChannels);\n  });\n});\n\ndescribe('seedRoot', () => {\n  it('starts every message with an empty object per emoji', () => {\n    expect(Object.keys(seedRoot('general', now).messages[0].reactions)).toEqual(\n      ['👍', '🎉', '👀', '❤️', '😂'],\n    );\n  });\n\n  it('greets #general with what to try', () => {\n    const { messages } = seedRoot('general', now);\n    expect(messages).toHaveLength(1);\n    expect(messages[0].userId).toBe('yorkie');\n    expect(messages[0].color).toBe('orange');\n    expect(messages[0].text).toMatch(/another tab/);\n    expect(messages[0].text).toMatch(/offline/);\n  });\n\n  it('seeds one line in the other channels', () => {\n    expect(seedRoot('design', now).messages).toHaveLength(1);\n  });\n});\n\ndescribe('addMessage', () => {\n  it('keeps the newest messagesMax messages', () => {\n    const doc = new Document<ChannelRoot>('test-trim');\n    doc.update((root) => {\n      root.messages = [] as unknown as JSONArray<Message>;\n    });\n    for (let i = 0; i <= messagesMax; i++) {\n      doc.update((root) => addMessage(root, message(`m${i}`)));\n    }\n    const { messages } = doc.getRoot();\n    expect(messages).toHaveLength(messagesMax);\n    expect(messages[0].id).toBe('m1');\n  });\n});\n\ndescribe('toggleReaction', () => {\n  it('counts each person once and keeps an emptied emoji', () => {\n    const doc = channelDoc();\n    const count = () =>\n      Object.keys(doc.getRoot().messages[0].reactions['👍'] ?? {}).length;\n\n    doc.update((root) => toggleReaction(root, 'm1', '👍', 'u1'));\n    doc.update((root) => toggleReaction(root, 'm1', '👍', 'u2'));\n    expect(count()).toBe(2);\n\n    doc.update((root) => toggleReaction(root, 'm1', '👍', 'u1'));\n    expect(count()).toBe(1);\n\n    doc.update((root) => toggleReaction(root, 'm1', '👍', 'u2'));\n    expect(count()).toBe(0);\n    expect(doc.getRoot().messages[0].reactions['👍']).toEqual({});\n  });\n\n  it('ignores an emoji outside the set', () => {\n    const doc = channelDoc();\n    doc.update((root) => toggleReaction(root, 'm1', '🦄', 'u1'));\n    expect(doc.getRoot().messages[0].reactions['🦄']).toBeUndefined();\n  });\n});\n\ndescribe('addReply', () => {\n  it('appends to the matching message only', () => {\n    const doc = channelDoc();\n    const { id, userId, name, color, text, at } = message('r1');\n    const reply = { id, userId, name, color, text, at };\n\n    doc.update((root) => addReply(root, 'm1', reply));\n    doc.update((root) => addReply(root, 'missing', reply));\n\n    expect(doc.getRoot().messages[0].replies).toHaveLength(1);\n    expect(doc.getRoot().messages[0].replies[0].id).toBe('r1');\n  });\n});\n"},{"isFile":true,"isOpen":false,"language":"typescript","name":"model.ts","path":"/src/model.ts","content":"import type { JSONArray, JSONObject } from '@yorkie-js/react';\n\n/** The colors a person can have. Orange is the brand's and stays out. */\nexport const peerColors = ['blue', 'green', 'purple', 'yellow', 'red'] as const;\nexport type PeerColor = (typeof peerColors)[number];\n\n/** A reply in a thread. The `Yorkie` guide message is the only orange one. */\nexport type Reply = {\n  id: string;\n  userId: string;\n  name: string;\n  color: PeerColor | 'orange';\n  text: string;\n  /**\n   * Sender's clock as an ISO string, for display only; order is the array\n   * order. (A millisecond number would not fit Yorkie's int32 and come back\n   * as a bigint.)\n   */\n  at: string;\n};\n\n/**\n * A message in a channel. A reaction is the key `reactions[emoji][userId]`,\n * so two people reacting at the same instant write different keys and both\n * count, and the same person can only count once.\n */\nexport type Message = Reply & {\n  reactions: Record<string, Record<string, true>>;\n  replies: Array<Reply>;\n};\n\nexport type ChannelInfo = { id: string; name: string };\n\n/** The workspace document: the channel list. Its presence is who is where. */\nexport type WorkspaceRoot = { channels: JSONArray<ChannelInfo> };\n\n/** One document per channel: its messages. */\nexport type ChannelRoot = { messages: JSONArray<Message> };\n\nexport type ChatPresence = {\n  userId: string;\n  name: string;\n  color: PeerColor;\n  /** When this pane joined (ISO). On a name or color clash, the earlier keeps it. */\n  joinedAt: string;\n  channelId: string;\n  typing: boolean;\n};\n\nexport const defaultChannels: Array<ChannelInfo> = [\n  { id: 'general', name: 'general' },\n  { id: 'design', name: 'design' },\n  { id: 'random', name: 'random' },\n];\n\nexport const textMax = 500;\nexport const messagesMax = 200;\nexport const emojis = ['👍', '🎉', '👀', '❤️', '😂'];\n\nconst names = [\n  'Ari',\n  'Ben',\n  'Cleo',\n  'Dana',\n  'Eli',\n  'Fern',\n  'Gus',\n  'Hana',\n  'Ivo',\n  'June',\n];\n\n// Control characters, the zero-width space, direction marks, line/paragraph\n// separators, bidi embeddings and isolates, and the BOM. Kept: line breaks,\n// so Shift+Enter can make a multi-line message; tabs, which the blank\n// collapse turns into spaces; and the zero-width (non-)joiners, which\n// compound emoji such as 👩‍💻 and scripts such as Persian need.\nconst unsafe =\n  // eslint-disable-next-line no-control-regex\n  /[\\u0000-\\u0008\\u000b-\\u001f\\u007f-\\u009f\\u200b\\u200e\\u200f\\u2028-\\u202e\\u2066-\\u2069\\ufeff]/g;\n\n/**\n * `normalizeText` is `raw` with unsafe characters removed, runs of blanks\n * collapsed (line breaks kept, at most two in a row), and trimmed.\n */\nexport function normalizeText(raw: string): string {\n  return raw\n    .replace(/\\r\\n?/g, '\\n')\n    .replace(unsafe, '')\n    .replace(/[^\\S\\n]+/g, ' ')\n    .replace(/ *\\n */g, '\\n')\n    .replace(/\\n{3,}/g, '\\n\\n')\n    .trim();\n}\n\n/**\n * `cleanText` returns `raw` as it may be sent: normalized and cut to\n * `textMax` code points. `undefined` means there is nothing to send.\n */\nexport function cleanText(raw: string): string | undefined {\n  return toSendable(normalizeText(raw));\n}\n\n/** `toSendable` cuts already normalized text to `textMax` code points. */\nexport function toSendable(normalized: string): string | undefined {\n  const out = [...normalized].slice(0, textMax).join('').trim();\n  return out.length ? out : undefined;\n}\n\n/**\n * `roomPrefix` is the key every document of this room starts with:\n * `?key=<prefix>` when given, else `react-chat-<YYYYMMDD>` (UTC), so everyone\n * opening the example on the same day shares one workspace.\n */\nexport function roomPrefix(search: string, now: Date): string {\n  const key = new URLSearchParams(search).get('key');\n  if (key) return key;\n  return `react-chat-${now.toISOString().slice(0, 10).replace(/-/g, '')}`;\n}\n\nexport function channelKey(prefix: string, channelId: string): string {\n  return `${prefix}-${channelId}`;\n}\n\n/**\n * `newId` is a random id. `crypto.randomUUID` exists only in secure contexts,\n * so a page opened over plain http (a phone on the LAN, say) falls back.\n */\nexport function newId(): string {\n  if (typeof crypto !== 'undefined' && crypto.randomUUID) {\n    return crypto.randomUUID();\n  }\n  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;\n}\n\n/**\n * `makeUser` makes a new person for this pane. It is kept in memory only:\n * the homepage's panes share one origin and one tab, so stored identity would\n * make every pane the same person.\n */\nexport function makeUser(\n  random: () => number = Math.random,\n): Pick<ChatPresence, 'userId' | 'name' | 'color' | 'joinedAt'> {\n  const pick = <T>(list: ReadonlyArray<T>) =>\n    list[Math.floor(random() * list.length) % list.length];\n  return {\n    userId: newId(),\n    name: pick(names),\n    color: pick(peerColors),\n    joinedAt: new Date().toISOString(),\n  };\n}\n\n/** Whether `other` keeps its name and color when it collides with `me`. */\nfunction outranks(other: ChatPresence, me: ChatPresence): boolean {\n  if (other.joinedAt !== me.joinedAt) return other.joinedAt < me.joinedAt;\n  return other.userId < me.userId;\n}\n\n/**\n * `resolveIdentity` returns the name and color `me` should have among\n * `others`. Random picks can collide, and panes that open together cannot see\n * each other yet when they pick, so every pane checks again as people arrive:\n * on a collision the one who joined later moves to a name or color nobody\n * has (ties go by `userId`), so all panes settle the same way.\n */\nexport function resolveIdentity(\n  me: ChatPresence,\n  others: Array<ChatPresence>,\n): Pick<ChatPresence, 'name' | 'color'> {\n  const seniors = others.filter((o) => outranks(o, me));\n  const usedNames = new Set(others.map((p) => p.name));\n  const usedColors = new Set(others.map((p) => p.color));\n  const name = seniors.some((o) => o.name === me.name)\n    ? (names.find((n) => !usedNames.has(n)) ?? me.name)\n    : me.name;\n  const color = seniors.some((o) => o.color === me.color)\n    ? (peerColors.find((c) => !usedColors.has(c)) ?? me.color)\n    : me.color;\n  return { name, color };\n}\n\nconst seedText: Record<string, string> = {\n  general:\n    'Welcome! Open this page in another tab to chat with yourself, react to this message from both at once, then take one tab offline and keep typing.',\n  design: 'Share mockups and feedback here.',\n  random: 'Anything goes.',\n};\n\n/**\n * `seedRoot` is the first content of a channel document for the day. It is\n * passed as `initialRoot`, which sets `messages` as one value, so two panes\n * creating the document at once end up with one array, not two. (If both\n * set it before either sees the other, one array wins, and a write made\n * into the losing one in that moment is dropped.)\n */\nexport function seedRoot(channelId: string, now: Date): ChannelRoot {\n  const seed: Message = {\n    id: `seed-${channelId}`,\n    userId: 'yorkie',\n    name: 'Yorkie',\n    color: 'orange',\n    text: seedText[channelId] ?? 'Say hello.',\n    at: now.toISOString(),\n    reactions: emptyReactions(),\n    replies: [],\n  };\n  return { messages: [seed] as JSONArray<Message> };\n}\n\n/**\n * `addMessage` appends `m` and drops the oldest past `messagesMax`. Two panes\n * trimming at once can leave a few over the cap; the next send trims them.\n */\nexport function addMessage(root: ChannelRoot, m: Message): void {\n  root.messages.push(m);\n  while (root.messages.length > messagesMax) {\n    root.messages.deleteByID(root.messages.getElementByIndex(0).getID());\n  }\n}\n\n/** `addReply` appends `r` to the thread of `messageId`, if it is still there. */\nexport function addReply(root: ChannelRoot, messageId: string, r: Reply): void {\n  // The stored message may be malformed (the room is public): skip it\n  // rather than throw.\n  const replies = root.messages.find((m) => m?.id === messageId)?.replies;\n  if (isList(replies)) replies.push(r);\n}\n\n/**\n * `emptyReactions` is a new message's reactions: one empty object per emoji,\n * made up front. If the first reaction created `reactions[emoji]`, two people\n * reacting at once would both create that key, and only one would survive.\n * With the objects already there, each writes its own `userId` key inside.\n * For the same reason an emoji is never deleted, only emptied.\n */\nexport function emptyReactions(): Record<string, Record<string, true>> {\n  return Object.fromEntries(emojis.map((e) => [e, {}]));\n}\n\n/** `toggleReaction` adds or removes `userId`'s `emoji` on `messageId`. */\nexport function toggleReaction(\n  root: ChannelRoot,\n  messageId: string,\n  emoji: string,\n  userId: string,\n): void {\n  const reactions = root.messages.find((m) => m?.id === messageId)?.reactions;\n  if (!isRecord(reactions)) return;\n  const people = reactions[emoji] as\n    | JSONObject<Record<string, true>>\n    | undefined;\n  if (!isRecord(people)) return;\n  if (people[userId]) {\n    delete people[userId];\n  } else {\n    people[userId] = true;\n  }\n}\n\n/** `reactionCount` is how many people reacted with one emoji. */\nexport function reactionCount(\n  people: Record<string, true> | undefined,\n): number {\n  return people ? Object.keys(people).length : 0;\n}\n\n// A Yorkie array is a Proxy, for which `Array.isArray` is false: test for\n// iterability instead.\nconst isList = (v: unknown): v is Iterable<unknown> =>\n  typeof v === 'object' &&\n  v !== null &&\n  typeof (v as Iterable<unknown>)[Symbol.iterator] === 'function';\n\nconst isRecord = (v: unknown): v is Record<string, unknown> =>\n  typeof v === 'object' && v !== null && !isList(v);\n\nfunction readReply(raw: unknown): Reply | undefined {\n  if (!isRecord(raw) || typeof raw.id !== 'string') return undefined;\n  const at = typeof raw.at === 'string' ? raw.at : '';\n  return {\n    id: raw.id,\n    userId: typeof raw.userId === 'string' ? raw.userId : '',\n    name:\n      (typeof raw.name === 'string' &&\n        [...(cleanText(raw.name) ?? '')].slice(0, 24).join('')) ||\n      'Someone',\n    color:\n      peerColors.includes(raw.color as PeerColor) || raw.color === 'orange'\n        ? (raw.color as Reply['color'])\n        : 'blue',\n    // Remote text gets the same cleanup and cap as text typed here: other\n    // clients are not bound by this one's composer.\n    text: typeof raw.text === 'string' ? (cleanText(raw.text) ?? '') : '',\n    at: Number.isNaN(Date.parse(at)) ? '' : at,\n  };\n}\n\n/**\n * `readMessage` is a stored message as it may be drawn, or `undefined` when\n * it cannot be. The daily room is public and any client can write any\n * shape, so one malformed message must not take every pane down with it.\n * An empty `at` means the time is unknown.\n */\nexport function readMessage(raw: unknown): Message | undefined {\n  const base = readReply(raw);\n  if (!base || !isRecord(raw)) return undefined;\n  const reactions: Message['reactions'] = {};\n  if (isRecord(raw.reactions)) {\n    // Only the fixed emoji set: a key is drawn as a chip label, and another\n    // client could store any string there.\n    for (const [emoji, people] of Object.entries(raw.reactions)) {\n      if (emojis.includes(emoji) && isRecord(people)) {\n        reactions[emoji] = Object.fromEntries(\n          Object.keys(people).map((id) => [id, true as const]),\n        );\n      }\n    }\n  }\n  const replies = isList(raw.replies)\n    ? uniqueById(Array.from(raw.replies, readReply))\n    : [];\n  return { ...base, reactions, replies };\n}\n\n/** `readMessages` is a channel's stored messages as they may be drawn. */\nexport function readMessages(raw: unknown): Array<Message> {\n  if (!isList(raw)) return [];\n  return uniqueById(Array.from(raw, readMessage));\n}\n\n/**\n * `uniqueById` drops missing entries and any entry whose id came earlier:\n * ids are React keys and the write helpers act on the first match.\n */\nfunction uniqueById<T extends { id: string }>(\n  list: Array<T | undefined>,\n): Array<T> {\n  const seen = new Set<string>();\n  return list.filter((x): x is T => {\n    if (!x || seen.has(x.id)) return false;\n    seen.add(x.id);\n    return true;\n  });\n}\n\n/**\n * `readChannels` is the workspace's stored channel list as it may be used:\n * ids that can go into a document key, falling back to the default channels\n * when nothing usable is stored.\n */\nexport function readChannels(raw: unknown): Array<ChannelInfo> {\n  if (!isList(raw)) return defaultChannels;\n  const seen = new Set<string>();\n  const out: Array<ChannelInfo> = [];\n  for (const c of raw) {\n    if (!isRecord(c) || typeof c.id !== 'string') continue;\n    if (!/^[a-z0-9-]{1,32}$/.test(c.id) || seen.has(c.id)) continue;\n    seen.add(c.id);\n    const name = typeof c.name === 'string' ? cleanText(c.name) : undefined;\n    out.push({ id: c.id, name: name ? [...name].slice(0, 32).join('') : c.id });\n  }\n  return out.length ? out : defaultChannels;\n}\n"},{"isFile":true,"isOpen":false,"language":"typescript","name":"vite-env.d.ts","path":"/src/vite-env.d.ts","content":"/// <reference types=\"vite/client\" />\n"}]},{"isFile":false,"name":"public","path":"/public","children":[{"isFile":true,"isOpen":false,"language":"ico","name":"favicon.ico","path":"/public/favicon.ico","content":""}]},{"isFile":true,"isOpen":false,"language":"","name":".gitignore","path":"/.gitignore","content":"# Logs\nlogs\n*.log\nnpm-debug.log*\nyarn-debug.log*\nyarn-error.log*\npnpm-debug.log*\nlerna-debug.log*\n\nnode_modules\ndist\ndist-ssr\n*.local\n\n# Editor directories and files\n.vscode/*\n!.vscode/extensions.json\n.idea\n.DS_Store\n*.suo\n*.ntvs*\n*.njsproj\n*.sln\n*.sw?\n"},{"isFile":true,"isOpen":false,"language":"markdown","name":"README.md","path":"/README.md","content":"# React Chat\n\nA Slack-like chat on Yorkie: channels, messages, emoji reactions, and\nthreads, with a rail that shows who is in which channel right now.\n\n<img width=\"500\" alt=\"React Chat\" src=\"./thumbnail.jpg\">\n\nThe thumbnail is a headless Chromium capture (Playwright, 2026-11-18) of\nthis example running against a local server: two panes side by side, a\nthird person in #design, a short conversation with a merged reaction and a\nreply, and one pane typing.\n\n## What to try\n\nOpen the page in two tabs (or add a user on yorkie.dev), then:\n\n1. **Presence.** Switch channel in one tab: its dot moves in the other's\n   rail. Start typing: the other shows \"… is typing\".\n2. **Reactions at the same instant.** React to the same message with the\n   same emoji from both tabs at once: the chip shows 2.\n3. **History.** Open a third tab: it gets the day's conversation.\n4. **Offline.** Press \"Go offline\" in one tab and send a few messages.\n   The other tab sees that person leave. Go online again: they come back\n   and their messages appear everywhere.\n\n## How it is built\n\n- **Documents.** One workspace document, `react-chat-<YYYYMMDD>`, holds the\n  channel list, and its presence holds each person's name, color, open\n  channel, and typing flag. Each channel is its own document,\n  `react-chat-<YYYYMMDD>-<channel>`, attached only while it is open. Add\n  `?key=<name>` to the URL to use a separate room.\n- **Reactions** are `reactions[emoji][userId] = true`. Every message starts\n  with an empty object per emoji, so two first reactions at once write two\n  keys instead of racing to create the same one.\n- **Threads** are a `replies` array inside the message.\n- **Offline** switches both documents to `SyncMode.Manual` with\n  `client.changeSyncMode`, and back to `SyncMode.Realtime`.\n- **Identity** is made in memory on each load (the panes on yorkie.dev\n  share storage). When two people get the same name or color, the one who\n  joined later picks a free one.\n\nThe data rules live in [`src/model.ts`](src/model.ts) and are tested in\n[`src/model.test.ts`](src/model.test.ts).\n\n## How to run\n\n1. Start the Yorkie server (from the repo root):\n   `docker compose -f docker/docker-compose.yml up --build -d`\n2. Install and build (from the repo root): `pnpm install` then `pnpm sdk build`\n   and `pnpm react build`\n3. `pnpm react-chat dev` (tests: `pnpm react-chat test`)\n4. Open the printed URL in two tabs.\n\nEach tab keeps two watch streams open, one per document. The local server\nspeaks HTTP/1.1, where a browser opens at most six connections to one host,\nso more than two tabs of this example in one browser can stall. yorkie.dev's\nserver uses HTTP/2 and has no such limit. Locally, use a second browser or a\nprivate window for a third person.\n"},{"isFile":true,"isOpen":false,"language":"mjs","name":"eslint.config.mjs","path":"/eslint.config.mjs","content":"import { globalIgnores } from 'eslint/config';\nimport prettierPlugin from 'eslint-plugin-prettier';\nimport reactHooks from 'eslint-plugin-react-hooks';\nimport reactRefresh from 'eslint-plugin-react-refresh';\nimport baseConfig from '../../eslint.config.mjs';\n\nconst eslintConfig = [\n  ...baseConfig,\n  reactHooks.configs.flat['recommended-latest'],\n  reactRefresh.configs.vite,\n  {\n    plugins: {\n      prettier: prettierPlugin,\n    },\n    rules: {\n      'prettier/prettier': 'error',\n      'jsdoc/require-jsdoc': 'off',\n    },\n  },\n  globalIgnores(['dist/*']),\n];\n\nexport default eslintConfig;\n"},{"isFile":true,"isOpen":false,"language":"markup","name":"index.html","path":"/index.html","content":"<!DOCTYPE html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <link rel=\"icon\" type=\"image/x-icon\" href=\"/favicon.ico\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <link\n      rel=\"stylesheet\"\n      href=\"https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css\"\n    />\n    <title>React Chat · Yorkie</title>\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.tsx\"></script>\n  </body>\n</html>\n"},{"isFile":true,"isOpen":false,"language":"json","name":"package.json","path":"/package.json","content":"{\n  \"name\": \"react-chat\",\n  \"private\": true,\n  \"version\": \"0.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"tsc && vite build\",\n    \"preview\": \"vite preview\",\n    \"test\": \"vitest run\"\n  },\n  \"dependencies\": {\n    \"@yorkie-js/react\": \"^0.7.29\",\n    \"@yorkie-js/sdk\": \"^0.7.29\",\n    \"react\": \"^19.2.1\",\n    \"react-dom\": \"^19.2.1\"\n  },\n  \"devDependencies\": {\n    \"@types/react\": \"^19.2.7\",\n    \"@types/react-dom\": \"^19.2.3\",\n    \"@vitejs/plugin-react\": \"^5.1.1\",\n    \"eslint-plugin-react-hooks\": \"^7.0.1\",\n    \"eslint-plugin-react-refresh\": \"^0.4.24\",\n    \"typescript\": \"^5.9.3\",\n    \"vite\": \"^7.3.7\",\n    \"vite-tsconfig-paths\": \"^5.1.4\",\n    \"vitest\": \"^4.1.12\"\n  }\n}\n"},{"isFile":true,"isOpen":false,"language":"json","name":"tsconfig.json","path":"/tsconfig.json","content":"{\n  \"compilerOptions\": {\n    \"target\": \"ESNext\",\n    \"useDefineForClassFields\": true,\n    \"lib\": [\"DOM\", \"DOM.Iterable\", \"ESNext\"],\n    \"allowJs\": false,\n    \"skipLibCheck\": true,\n    \"esModuleInterop\": false,\n    \"allowSyntheticDefaultImports\": true,\n    \"strict\": true,\n    \"forceConsistentCasingInFileNames\": true,\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"Node\",\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"noEmit\": true,\n    \"jsx\": \"react-jsx\",\n    \"paths\": {\n      \"@yorkie-js/sdk/src/*\": [\"../../packages/sdk/src/*\"]\n    }\n  },\n  \"include\": [\"src\"],\n  \"references\": [{ \"path\": \"./tsconfig.node.json\" }]\n}\n"},{"isFile":true,"isOpen":false,"language":"json","name":"tsconfig.node.json","path":"/tsconfig.node.json","content":"{\n  \"compilerOptions\": {\n    \"composite\": true,\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"Node\",\n    \"allowSyntheticDefaultImports\": true\n  },\n  \"include\": [\"vite.config.ts\"]\n}\n"},{"isFile":true,"isOpen":false,"language":"typescript","name":"vite.config.ts","path":"/vite.config.ts","content":"import path from 'path';\nimport { defineConfig } from 'vite';\nimport react from '@vitejs/plugin-react';\nimport tsconfigPaths from 'vite-tsconfig-paths';\n\n// https://vitejs.dev/config/\nexport default defineConfig({\n  base: '',\n  plugins: [react(), tsconfigPaths()],\n  resolve: {\n    alias: [\n      {\n        find: '@yorkie-js/react',\n        replacement: path.resolve(__dirname, '../../packages/react/src'),\n      },\n      {\n        find: '@yorkie-js/sdk/src',\n        replacement: path.resolve(__dirname, '../../packages/sdk/src'),\n      },\n    ],\n  },\n});\n"}]}